var CryptoJS = require('crypto-js');

function _pad(n) { return n < 10 ? '0' + n : '' + n; }

function utcNow() {
  var d = new Date();
  return '' + d.getUTCFullYear() + _pad(d.getUTCMonth()+1) + _pad(d.getUTCDate()) +
         _pad(d.getUTCHours()) + _pad(d.getUTCMinutes()) + _pad(d.getUTCSeconds());
}

function hmac512(msg, secret) {
  return CryptoJS.enc.Base64.stringify(CryptoJS.HmacSHA512(msg, secret));
}

function b64(str) {
  return CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(str));
}

function b64json(obj) {
  if (typeof obj === 'string') return b64(obj);
  return b64(JSON.stringify(obj));
}

function ensureB64(url) {
  url = (url || '').trim();
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return b64(url);
  return url;
}

function fmtAmt(a, cur) { var n = parseFloat(a) || 0; if (String(cur || '').toUpperCase() === 'KHR') return String(Math.round(n)); return n.toFixed(2); }
function genTranId() { return 'T' + Date.now().toString(); }
function genRequestId(p) { return (p || 'REQ') + Date.now().toString().slice(-12); }
function okStatus(j) { return !!(j && j.status && (String(j.status.code) === '0' || String(j.status.code) === '00')); }
function respCode(j) { return j && j.status ? String(j.status.code) : ''; }
function rsaMissing(j) {
  // true when the gateway rejected the call only because the RSA payload (merchant_auth / beneficiaries) was empty
  var errs = (j && j.errors) || (j && j.status && j.status.errors) || null;
  var code = String((j && j.statusCode) || (j && j.status && j.status.code) || '');
  if (code !== '04') return false;
  return !!errs && /merchant_auth|beneficiaries/i.test(Object.keys(errs).join(' '));
}

function openSslEncrypt(jsonStr, pem) {
  var forge = null;
  try { forge = require('node-forge'); } catch (e) {}
  if (!forge) return null;
  var key = forge.pki.publicKeyFromPem(pem);
  var keyByteLen = Math.ceil(key.n.bitLength() / 8);
  var chunkLen = keyByteLen - 11;
  var bin = forge.util.createBuffer(jsonStr, 'utf8').getBytes();
  var out = '';
  for (var i = 0; i < bin.length; i += chunkLen) {
    out += key.encrypt(bin.substring(i, i + chunkLen), 'RSAES-PKCS1-V1_5');
  }
  return forge.util.encode64(out);
}

function rsaFallback(jsonStr, pem, fallbackVar) {
  var enc = openSslEncrypt(jsonStr, pem);
  if (enc) return enc;
  var fb = pm.collectionVariables.get(fallbackVar) || '';
  if (!fb) {
    console.log('WARN: node-forge unavailable and {{' + fallbackVar + '}} is empty. Install the node-forge library or paste a pre-computed value.');
  }
  return fb;
}

// ---- JSON Schema assertions (draft-04 subset) ----
// Usage: assertJsonSchema({ required: ['status', 'data'], properties: { status: { type: 'object' } } })
function assertJsonSchema(schema, expected) {
  if (typeof expected === 'undefined') expected = 200;
  pm.test('HTTP ' + expected, function () { pm.response.to.have.status(expected); });
  if (!schema) { pm.test('JSON Schema defined', function () { pm.expect(schema).to.not.be.empty; }); return; }
  pm.test('Response matches JSON Schema', function () {
    pm.response.to.have.jsonSchema(schema);
  });
}
function escHtml(s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }
// ---- Postman Visualizer helpers (no-ops in newman/CI) ----
function visualizeFormPost(action, fields, title, note) {
  if (typeof pm.visualizer === 'undefined' || !pm.visualizer.set) return;
  var inputs = '';
  for (var k in fields) {
    inputs += '<input type="hidden" name="' + escHtml(k) + '" value="' + escHtml(fields[k]) + '">';
  }
  var tpl = '<html><head><meta charset="utf-8"><style>body{font:14px/1.5 sans-serif;margin:0;height:100vh;display:flex;align-items:center;justify-content:center;background:#fafafa;color:#222}.card{max-width:560px;background:#fff;border:1px solid #e5e5e5;border-radius:10px;padding:24px;box-shadow:0 1px 4px rgba(0,0,0,.06)}h4{margin:0 0 8px}p{margin:0 0 16px;color:#555;font-size:13px}button{font:600 14px sans-serif;padding:10px 18px;border:0;border-radius:8px;background:#0a7d38;color:#fff;cursor:pointer}</style></head><body><div class="card"><h4>{{title}}</h4><p>{{note}}</p><form method="POST" action="{{action}}">{{{inputs}}}<button type="submit">Open payment page &rarr;</button></form></div></body></html>';
  pm.visualizer.set(tpl, { title: String(title || ''), note: String(note || ''), action: String(action || ''), inputs: inputs });
}
function visualizeQr(dataUrl, qrText, title) {
  if (typeof pm.visualizer === 'undefined' || !pm.visualizer.set) return;
  var img = dataUrl
    ? '<img alt="QR code" style="width:300px;height:300px" src="' + dataUrl + '">'
    : '<div id="qrbox">Rendering QR...</div>' +
      '<script src="https://cdn.jsdelivr.net/gh/davidshimjs/qrcodejs/qrcode.min.js"><\/script>' +
      '<script>try { new QRCode(document.getElementById("qrbox"), { text: ' + JSON.stringify(String(qrText || '')).replace(/</g, '\\u003c') + ', width: 300, height: 300 }); } catch (e) { document.getElementById("qrbox").textContent = "QR render failed - copy the string below into any QR tool."; }<\/script>';
  var tpl = '<html><head><meta charset="utf-8"><style>body{font:14px sans-serif;margin:16px;color:#222}code{display:block;white-space:pre-wrap;word-break:break-all;background:#f4f4f5;padding:10px;border-radius:6px;margin-top:14px;font-size:11px}h4{margin:0 0 12px}</style></head><body><h4>{{title}}</h4>{{{img}}}{{#if qrText}}<code>{{qrText}}</code>{{/if}}</body></html>';
  pm.visualizer.set(tpl, { title: String(title || 'Scan with the ABA Mobile app'), img: img, qrText: String(qrText || '') });
}
